// pybytes.mjs
// Replicates Python's bytes type behavior needed by this program:
// UTF-8 encoding of strings and the repr() formatting used by print().

// Equivalent of Python's str.encode() (default UTF-8).
// Returns a plain Array of byte values (0-255).
export function encodeUtf8(str) {
  const bytes = [];
  for (const ch of str) {
    const code = ch.codePointAt(0);
    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code < 0x10000) {
      bytes.push(
        0xe0 | (code >> 12),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (code >> 18),
        0x80 | ((code >> 12) & 0x3f),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    }
  }
  return bytes;
}

function hex2(n) {
  return n.toString(16).padStart(2, "0");
}

// Equivalent of Python's repr(bytes) / print(bytes).
// bytesObj is an Array of byte values (0-255).
export function bytesRepr(bytesObj) {
  // Python prefers single quotes, switching to double quotes only when
  // the data contains a single quote but no double quote.
  const hasSingle = bytesObj.includes(0x27);
  const hasDouble = bytesObj.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let out = "b" + quoteChar;
  for (const b of bytesObj) {
    if (b === 0x5c) {
      out += "\\\\";
    } else if (b === quote) {
      out += "\\" + quoteChar;
    } else if (b === 0x09) {
      out += "\\t";
    } else if (b === 0x0a) {
      out += "\\n";
    } else if (b === 0x0d) {
      out += "\\r";
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += "\\x" + hex2(b);
    }
  }
  out += quoteChar;
  return out;
}

// construct.mjs
// Minimal black-box reimplementation of the `construct` library features
// used by the original Python script: Int8ul and Bytes(n).
// Built values are plain Arrays of byte values (0-255).

export class FormatFieldError extends Error {
  constructor(message) {
    super(message);
    this.name = "FormatFieldError";
  }
}

export class StreamError extends Error {
  constructor(message) {
    super(message);
    this.name = "StreamError";
  }
}

// Unsigned 8-bit integer, little-endian (trivially one byte).
// construct.Int8ul.build(obj)
export const Int8ul = {
  build(obj) {
    if (!Number.isInteger(obj) || obj < 0 || obj > 255) {
      // Mirrors: struct.error: 'B' format requires 0 <= number <= 255
      throw new FormatFieldError(
        "Error in path (building)\n" +
          `struct '<B' error during building, given value ${obj}`,
      );
    }
    return [obj];
  },
};

// Fixed-length byte string. construct.Bytes(length).build(bytesObj)
// bytesObj is an Array of byte values; its length must match exactly.
export function Bytes(length) {
  return {
    build(bytesObj) {
      if (bytesObj.length !== length) {
        throw new StreamError(
          `Error in path (building)\nexpected ${length} bytes, found ${bytesObj.length}`,
        );
      }
      return bytesObj.slice();
    },
  };
}

// argparse.mjs
// Minimal reimplementation of the argparse behavior used by the original
// Python script: long options with required values, `--name=value` syntax,
// required-argument enforcement, Python-int conversion, usage/error output
// (stderr, exit code 2) and -h/--help (stdout, exit code 0).

import { basename } from "node:path";

// Python's int(str): optional surrounding whitespace, optional sign,
// decimal digits with single underscores allowed between digits.
export function parsePythonInt(text) {
  const s = String(text).trim();
  if (!/^[+-]?\d+(?:_\d+)*$/.test(s)) {
    return null;
  }
  return parseInt(s.replace(/_/g, ""), 10);
}

export class ArgumentParser {
  constructor(options = {}) {
    this.prog = options.prog || basename(process.argv[1] || "prog");
    this.arguments = [];
    // -h/--help is implicit, listed first like argparse does.
    this.addArgument(["-h", "--help"], {
      dest: "help",
      takesValue: false,
      help: "show this help message and exit",
    });
  }

  addArgument(flags, opts = {}) {
    const list = Array.isArray(flags) ? flags : [flags];
    const longest = list.find((f) => f.startsWith("--")) || list[0];
    const dest =
      opts.dest || longest.replace(/^--?/, "").replace(/-/g, "_");
    this.arguments.push({
      flags: list,
      dest,
      takesValue: opts.takesValue !== false,
      required: !!opts.required,
      type: opts.type || "str",
      metavar: opts.metavar || dest.toUpperCase(),
      help: opts.help || "",
    });
  }

  _byFlag(flag) {
    return this.arguments.find((a) => a.flags.includes(flag));
  }

  usageLine() {
    const parts = [];
    for (const arg of this.arguments) {
      if (arg.dest === "help") {
        parts.push("[-h]");
      } else if (arg.required) {
        parts.push(`${arg.flags[arg.flags.length - 1]} ${arg.metavar}`);
      } else {
        parts.push(`[${arg.flags[arg.flags.length - 1]} ${arg.metavar}]`);
      }
    }
    return `usage: ${this.prog} ${parts.join(" ")}`;
  }

  helpText() {
    let out = this.usageLine() + "\n\noptions:\n";
    for (const arg of this.arguments) {
      const left = arg.takesValue
        ? arg.flags.map((f) => `${f} ${arg.metavar}`).join(", ")
        : arg.flags.join(", ");
      out += `  ${left}`;
      if (arg.help) {
        // Align like argparse's help formatter (help position at column 24).
        const pad = Math.max(1, 24 - 2 - left.length);
        out += " ".repeat(pad) + arg.help;
      }
      out += "\n";
    }
    return out;
  }

  error(message) {
    process.stderr.write(this.usageLine() + "\n");
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv) {
    const values = {};
    for (const arg of this.arguments) {
      if (arg.dest !== "help") values[arg.dest] = undefined;
    }

    const extras = [];
    let i = 0;
    while (i < argv.length) {
      let token = argv[i];
      let inlineValue = null;

      if (token.startsWith("--") && token.includes("=")) {
        const eq = token.indexOf("=");
        inlineValue = token.slice(eq + 1);
        token = token.slice(0, eq);
      }

      if (token.startsWith("-") && token !== "-") {
        const arg = this._byFlag(token);
        if (!arg) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (arg.dest === "help") {
          process.stdout.write(this.helpText());
          process.exit(0);
        }
        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
        } else {
          if (i + 1 >= argv.length || argv[i + 1].startsWith("--")) {
            this.error(`argument ${arg.flags.join("/")}: expected one argument`);
          }
          raw = argv[i + 1];
          i += 1;
        }
        if (arg.type === "int") {
          const parsed = parsePythonInt(raw);
          if (parsed === null) {
            this.error(
              `argument ${arg.flags.join("/")}: invalid int value: '${raw}'`,
            );
          }
          values[arg.dest] = parsed;
        } else {
          values[arg.dest] = raw;
        }
        i += 1;
      } else {
        extras.push(token);
        i += 1;
      }
    }

    const missing = this.arguments
      .filter((a) => a.required && values[a.dest] === undefined)
      .map((a) => a.flags[a.flags.length - 1]);
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.join(", ")}`,
      );
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(" ")}`);
    }
    return values;
  }
}

// test8.mjs
// Node.js (ESM) port of /workspace/dataset/construct/test8.py
// Run: node test8.mjs --a <int> --b <int> --c <str>

import { ArgumentParser } from "./lib/argparse.mjs";
import { Int8ul, Bytes } from "./lib/construct.mjs";
import { encodeUtf8, bytesRepr } from "./lib/pybytes.mjs";

function main() {
  const parser = new ArgumentParser();
  parser.addArgument("--a", { type: "int", required: true });
  parser.addArgument("--b", { type: "int", required: true });
  parser.addArgument("--c", { type: "str", required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  let format1, format2, format3;
  try {
    format1 = Int8ul.build(args.a); // 构建第一个整数
    format2 = Int8ul.build(args.b); // 构建第二个整数
    const length = encodeUtf8(args.c).length;
    format3 = Bytes(length).build(encodeUtf8(args.c)); // 构建字节串
  } catch (err) {
    // Python lets the construct exception propagate: traceback on stderr,
    // exit code 1.
    process.stderr.write(`${err.name}: ${err.message}\n`);
    process.exit(1);
  }

  console.log(bytesRepr(format1));
  console.log(bytesRepr(format2));
  console.log(bytesRepr(format3));
}

main();

